import{_ as a,o,c as t,a3 as s}from"./chunks/framework.DMtjdCb-.js";const n="/help/assets/work-detail.en.MTBKpUk_.png",i="/help/assets/playback.en.BCEbjiXn.png",y=JSON.parse('{"title":"5. Start watching","description":"","frontmatter":{},"headers":[],"relativePath":"en/playback.md","filePath":"en/playback.md"}'),r={name:"en/playback.md"};function l(p,e,c,d,h,g){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="_5-start-watching" tabindex="-1">5. Start watching <a class="header-anchor" href="#_5-start-watching" aria-label="Permalink to &quot;5. Start watching&quot;">​</a></h1><p>Once media is accessible, choose an episode and a player in title details. The player runs on the computer or phone you are using; AnimeMachine can run on the NAS.</p><h2 id="play-an-episode-on-your-pc" tabindex="-1">Play an episode on your PC <a class="header-anchor" href="#play-an-episode-on-your-pc" aria-label="Permalink to &quot;Play an episode on your PC&quot;">​</a></h2><ol><li>Open title details and find <strong>Playback</strong>.</li><li>If several sources or DVD/BD editions exist, select the source and edition.</li><li>Choose the starting episode and select <strong>Open in PotPlayer</strong> or <strong>Open in VLC</strong>.</li><li>Accept the browser&#39;s request to open the external app.</li></ol><p><img src="'+n+'" alt="Playback: choose a source, edition, episode, and player" loading="lazy"></p><p><strong>Expected result:</strong> the player starts the selected episode. To play several titles consecutively, use <a href="./continue-watching.html">Continue watching</a>.</p><h2 id="save-precise-positions-with-potplayer" tabindex="-1">Save precise positions with PotPlayer <a class="header-anchor" href="#save-precise-positions-with-potplayer" aria-label="Permalink to &quot;Save precise positions with PotPlayer&quot;">​</a></h2><ol><li>Choose <strong>Install progress extension</strong> to download the extension package.</li><li>Close PotPlayer. Follow the package&#39;s <code>README.txt</code> to merge its <code>Extension</code> folder into the PotPlayer installation folder.</li><li>Restart PotPlayer and begin playback through AnimeMachine.</li></ol><p>The extension saves precise positions and resumes five seconds before the last stop. Without it, playback still works and media access records episodes. Records belong to the account that generated the playlist.</p><h2 id="repeated-browser-launch-prompts" tabindex="-1">Repeated browser launch prompts <a class="header-anchor" href="#repeated-browser-launch-prompts" aria-label="Permalink to &quot;Repeated browser launch prompts&quot;">​</a></h2><p>In Edge or Chrome on Windows, choose <strong>Copy permission command</strong>, press <code>Win + R</code>, enter <code>cmd</code>, press Enter, paste and run the command, then reopen the browser.</p><p><img src="'+i+'" alt="Player controls: permission command and progress extension" loading="lazy"></p><p>The command allows this site to open PotPlayer and VLC for your Windows account, preserving existing permissions. If copying is blocked, a dialog selects the complete command; use <code>Ctrl+C</code>, then paste it into <code>cmd</code>.</p><h2 id="phones-copied-links-and-downloaded-playlists" tabindex="-1">Phones, copied links, and downloaded playlists <a class="header-anchor" href="#phones-copied-links-and-downloaded-playlists" aria-label="Permalink to &quot;Phones, copied links, and downloaded playlists&quot;">​</a></h2><p>Install VLC on the phone, then choose <strong>Open in VLC</strong> in its browser. You can also copy the playlist address into the player&#39;s network-stream field, or download and open the M3U file.</p><p>These methods retain the account associated when the playlist was generated. Media requests indicate an episode was accessed; <strong>ordinary VLC media requests cannot report an exact stopping position</strong>. Prefetching can also access an episode early. <a href="./continue-watching.html#correct">Correct the record</a> when needed.</p><p>A playlist contains the episodes available when it was generated. Generate another list after new episodes arrive.</p>',17)])])}const u=a(r,[["render",l]]);export{y as __pageData,u as default};
